using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Design; namespace KKBOT.Persistence; public sealed class DesignTimeDbContextFactory : IDesignTimeDbContextFactory<KkbBotDbContext> { public KkbBotDbContext CreateDbContext(string[] args) { var options = new DbContextOptionsBuilder<KkbBotDbContext>() .UseSqlite("Data Source=kkbot.db") .Options; return new KkbBotDbContext(options); } }